{
  "title": "图书馆的奇幻冒险",
  "scene": "小明今天早上起床后，发现校巴上放着一本神秘的书。书的封面是蓝色的，上面有闪闪发光的星星图案。小明好奇地捡起书，书在空中旋转了几圈后，突然变成了一扇通往图书馆的门。小明推开门，发现自己站在了一个充满魔法的图书馆里。",
  "goal": "帮助小明找到通往现实世界的门，同时收集至少三颗魔法宝石。",
  "choices": [
    {
      "id": "A",
      "text": "向左走，去一个看起来像仙境的小房间。",
      "outcome": "小明发现了一个装有魔法宝石的盒子，但门却被锁住了。",
      "result": "partial",
      "next": "图书馆的奇幻冒险-2"
    },
    {
      "id": "B",
      "text": "向右走，去一个书架林立的大厅。",
      "outcome": "小明找到了一把钥匙，但钥匙却无法打开盒子。",
      "result": "partial",
      "next": "图书馆的奇幻冒险-3"
    },
    {
      "id": "C",
      "text": "回到图书馆门口，看看是否有其他线索。",
      "outcome": "小明在门口的石碑上发现了提示，提示他需要找到所有的魔法宝石。",
      "result": "success",
      "next": "图书馆的奇幻冒险-4"
    }
  ]
}
